INSERT INTO twin_scan_delay_request (
    subject_user_id, card_no, room_id, option_id, duration_minutes,
    reviewer_user_id, status, requested_by, created_at
) VALUES (
    #{subjectUserId}, #{cardNo}, #{roomId}, #{optionId}, #{durationMinutes},
    #{reviewerUserId}, #{status}, #{requestedBy}, #{createdAt}
