mapper.select:
SELECT * FROM twin_scan_delay_request
WHERE status = 'PENDING' AND DATE(created_at) = CURDATE()
  AND reviewer_user_id = #{reviewerUserId}
ORDER BY created_at DESC
LIMIT #{limit}

SELECT * FROM twin_scan_delay_request
WHERE subject_user_id = #{subjectUserId}
  AND status IN ('PENDING', 'APPROVED', 'REJECTED')
ORDER BY COALESCE(reviewed_at, created_at) DESC
LIMIT #{limit}

SELECT * FROM twin_scan_delay_request
WHERE subject_user_id = #{subjectUserId}
  AND room_id = #{roomId}
  AND status IN ('PENDING', 'APPROVED')
ORDER BY created_at DESC
LIMIT 5

SELECT COUNT(1) FROM twin_scan_delay_request
WHERE subject_user_id = #{subjectUserId}
  AND room_id = #{roomId}
  AND option_id = #{optionId}
  AND DATE(created_at) = CURDATE()
  AND status != 'DELETED'

SELECT DISTINCT option_id FROM twin_scan_delay_request
WHERE subject_user_id = #{subjectUserId}
  AND room_id = #{roomId}
  AND status = 'REJECTED'
  AND DATE(created_at) = CURDATE()
